        return max(0, min(a['end'], b['end']) - max(a['start'], b['start']))

    def cut_speed(event1, event2):
        start_overlap = overlap(event1, event2)
        end_overlap = overlap(event2, event1)

        # Check if event1 ends before event2 starts or vice versa
        if event1['end'] < event2['start']:
            return event1['end'] < event2['start']

        # If they don't overlap, check if event1 finishes before event2 begins
        elif start_overlap == 0:
            return event1['end'] < event2['start']

        # Event1 overlaps with event2
        else:
            return start_overlap + end_overlap <= 0.5

    for i in range(len(events)):
        for j in range(i+1, len(events)):
            if cut_speed(events[i], events[j]):
                return True
    return False
