    return max(0, min(a['end'], b['end']) - max(a['start'], b['start']))

def matches(events):
    def cut_speed_before_stationary(event1, event2):
        # Check if event1 ends before event2 starts or if they overlap but don't meet the criteria
        if event1['end'] < event2['start']:
            return False

        # Calculate overlap between event1 and event2
        overlap_value = overlaps(event1, event2)

        # Check if overlap is within acceptable range
        if 0.5 > overlap_value >= 0:
            return False

        # Check if event2 starts after event1 ends by at least 5 seconds
        if event2['start'] - event1['end'] < 5:
            return False

        return True

    # Iterate through each pair of events
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if cut_speed_before_stationary(events[i], events[j]):
                return True

    return False
```

