    # Check if there are at least two events
    if len(events) < 2:
        return False

    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event
    for i in range(len(events)):
        current_event = events[i]

        # Skip if this is the first event or it doesn't follow the previous event
        if i == 0 or not overlaps(current_event, events[i-1]):
            continue

        # Check if the next event follows the current event
        next_event = events[i+1] if i + 1 < len(events) else None
        if next_event and not following(current_event, next_event):
            return False

    return True

