def matches(events):
    # Check if there are at least two events
    if len(events) < 2:
        return False

    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event
    for i in range(len(events)):
        current_event = events[i]

        # If this event starts after the last event ended, break out of loop
        if i > 0 and events[i-1]['end'] > current_event['start']:
            break

        # Check if previous event overlaps with current event
        prev_event = events[i-1] if i > 0 else None
        if prev_event and overlap(prev_event, current_event) > 0.5:
            continue

        # Check if next event overlaps with current event
        next_event = events[i+1] if i + 1 < len(events) else None
        if next_event and overlap(next_event, current_event) > 0.5:
            continue

        # Check if current event overlaps with any other event
        for j in range(i+1, len(events)):
            if overlap(current_event, events[j]) > 0.5:
                return True

    return False


