def overlaps(a, b):
    return max(0, min(a['end'], b['end']) - max(a['start'], b['start']))

def matches(events):
    def cut_speed(event1, event2):
        # Check if the first event changes direction after the second event starts
        if event1['start'] + 0.5 < event2['start']:
            return False

        # Calculate the overlap between the two events
        overlap_time = overlaps(event1, event2)

        # If there is no overlap or the overlap is less than half the duration of either event,
        # they do not satisfy the condition
        if overlap_time == 0 or overlap_time < 0.5:
            return False

        # Check if the start of the second event is within 5 seconds of the end of the first event
        if abs(event2['start'] - event1['end']) > 5:
            return False

        # The events satisfy the condition if the overlap is at least 80% of the shorter duration
        return overlap_time >= 0.8 * min(event1['duration'], event2['duration'])

    # Iterate through each pair of consecutive events to check if any pair satisfies the condition
    for i in range(len(events) - 1):
        if cut_speed(events[i], events[i+1]):
            return True

    return False
```

