import math

def matches(events) -> bool:
    def overlap(a, b):
        return max(0, min(a['end'], b['end']) - max(a['start'], b['start']))

    def is_stationary(event):
        return event['type'] == 'STOP' or event['type'] == 'DECELERATE'

    def is_left_turn(event):
        return event['type'] == 'TURN' and event['start'] > 0.5

    def is_while(event1, event2):
        return overlap(event1, event2) > 0.5 and abs(event2['start'] - event1['end']) <= 5.0

    def is_then(event1, event2):
        return event1['start'] < event2['start'] and overlap(event1, event2) <= 0.5 and -0.5 <= event2['start'] - event1['end'] <= 5.0

    stationary_events = [event for event in events if is_stationary(event)]
    left_turn_events = [event for event in events if is_left_turn(event)]

    for i in range(len(left_turn_events)):
        for j in range(i + 1, len(left_turn_events)):
            if is_while(left_turn_events[i], left_turn_events[j]):
                return True

    return False
