        return max(0, min(a['end'], b['end']) - max(a['start'], b['start']))

    def is_stationary(event):
        return event['type'] == 'STOP' and event['end'] - event['start'] >= 10

    def change_direction(event):
        return event['type'] == 'TURN'

    def is_while(event):
        prev_event = events[-2] if len(events) > 1 else None
        next_event = events[1] if len(events) > 1 else None
        return prev_event and next_event and change_direction(prev_event) and change_direction(next_event)

    def is_then(event):
        prev_event = events[-2] if len(events) > 1 else None
        next_event = events[1] if len(events) > 1 else None
        return prev_event and next_event and is_stationary(prev_event) and is_stationary(next_event)

    for i in range(len(events)):
        current_event = events[i]
        if is_stationary(current_event):
            if i + 1 < len(events) and is_while(events[i+1]):
                return True
            elif i + 2 < len(events) and is_then(events[i+1], events[i+2]):
                return True
    return False
