def overlaps(a, b):
    return max(0, min(a['end'], b['end']) - max(a['start'], b['start']))

def matches(events):
    def check_sentence(sentence):
        for i in range(len(events)):
            for j in range(i + 1, len(events)):
                if sentence == 'then':
                    if events[i]['type'] != 'STOP' or events[j]['type'] != 'DECELERATE':
                        continue
                    if overlaps(events[i], events[j]) <= 0.5:
                        continue
                    if abs(events[j]['start'] - events[i]['end']) <= 5.0:
                        return True
                elif sentence == 'while':
                    if events[i]['type'] != 'STOP' or events[j]['type'] != 'ACCELERATE':
                        continue
                    if overlaps(events[i], events[j]) > 0.5:
                        continue
                    if abs(events[j]['start'] - events[i]['end']) >= 0.8 * min(events[i]['duration'], events[j]['duration']):
                        return True
        return False

    sentences = ['then', 'while']
    for sentence in sentences:
        if check_sentence(sentence):
            return True
    return False
