    def condition1(start, end):
        return start < end and overlap(start, end) <= 0.5 and -0.5 <= end - start <= 5.0

    def condition2(start, end):
        return overlap(start, end) > 0.5 and overlap(start, end) >= 0.8 * min(end - start, start)

    for i in range(len(events)):
        for j in range(i + 1, len(events)):
