            event_j = events[j]

            # Check if either event starts after the other ends or they have an overlap less than 0.5
            if event_i['start'] > event_j['end'] or overlap(event_i, event_j) < 0.5:
                continue

            # Check if both events occur at the same time
            if event_i['start'] == event_j['start']:
                if condition1(event_i['start'], event_i['end']):
                    return True
                elif condition2(event_i['start'], event_i['end']):
                    return True

    return False
