def matches(events):
    # Define event types
    TURN = 'TURN'
    DECELERATE = 'DECELERATE'
    ACCELERATE = 'ACCELERATE'
    STOP = 'STOP'

    def overlap(a, b):
        return max(0, min(a['end'], b['end']) - max(a['start'], b['start']))

    def is_turn(event1, event2):
        return event1['type'] == TURN and event2['type'] == ACCELERATE

    def is_decelerate(event1, event2):
        return event1['type'] == DECELERATE and event2['type'] == ACCELERATE

    def is_accelerate(event1, event2):
        return event1['type'] == ACCELERATE and event2['type'] == DECELERATE

    def is_stop(event1, event2):
        return event1['type'] == STOP and event2['type'] == DECELERATE

    def is_while(event1, event2):
        overlap_value = overlap(event1, event2)
        return overlap_value > 0.5 and overlap_value >= 0.8 * min(event1['duration'], event2['duration'])

    # Check all pairs of events to see if they satisfy the conditions
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if is_turn(events[i], events[j]) or \
               is_decelerate(events[i], events[j]) or \
               is_accelerate(events[i], events[j]) or \
               is_stop(events[i], events[j]) or \
               is_while(events[i], events[j]):
                return True
    return False
