    for i in range(len(events)):
        current_event = events[i]

        # Check if this event ends after the previous event starts
        if i > 0:
            prev_event = events[i-1]
            if current_event['end'] > prev_event['start']:
                return False

        # Check if there was another event happening at the same time as this one
        for j in range(i+1, len(events)):
            next_event = events[j]
            if current_event['type'] == 'STOP' and next_event['type'] != 'STOP':
                continue

            overlap = overlap(current_event, next_event)

            if current_event['type'] == 'DECELERATE':
                if overlap > 0.5 or overlap < 0.8 * min(current_event['duration'], next_event['duration']):
                    return False
            elif current_event['type'] == 'ACCELERATE':
                if overlap < 0.5 or overlap > 0.8 * min(current_event['duration'], next_event['duration']):
                    return False
            else:
                if overlap > 0.5:
