def matches(events: List[Dict[str, float]]) -> bool:
    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    prev_end_time = None

    for event in events:
        if 'DECELERATE' in event['type']:
            if prev_end_time is not None:
                # Check if there was an acceleration or stop between this deceleration and the previous event
                if 'ACCELERATE' in prev_event['type'] or 'STOP' in prev_event['type']:
                    return True

                # Check if the current deceleration overlaps with any other event within 1 second
                for i in range(len(events)):
                    if i != len(events) - 1 and overlap(events[i], events[i + 1]) <= 0.5:
                        return True

            # If no overlapping events found, check if it meets the criteria for being a single event
            if overlap(event, events[-1]) > 0.5 and overlap(event, events[-1]) >= 0.8 * min(event['duration'], events[-1]['duration']):
                return True

        prev_end_time = event['end']

    return False


