    events.sort(key=lambda x: x['start'])

    # Iterate through each event to check if it can be part of any other event
    for i in range(len(events)):
        current_event = events[i]

        # Check if this event overlaps with previous or next events
        for j in range(i-1, -1, -1):
            prev_event = events[j]
            overlap_with_prev = overlap(prev_event, current_event)

            for k in range(j+1, len(events)):
                next_event = events[k]
                overlap_with_next = overlap(next_event, current_event)

                # If there's an overlap between this event and either previous or next event
                if overlap_with_prev > 0.5:
                    return True

                if overlap_with_next > 0.5:
                    return True

        # If no overlap found, add this event as a standalone event
        events.append(current_event)

    return False

