    events.sort(key=lambda x: x['start'])

    # Iterate through each event
    for i in range(len(events)):
        current_event = events[i]

        # Check if this event ends after the previous event starts
        if i > 0:
            prev_event = events[i-1]
            if current_event['end'] > prev_event['start']:
                return False

        # Check if there was an overlapping event
        for j in range(i+1, len(events)):
            next_event = events[j]
            if current_event['type'] == 'STOP' or next_event['type'] == 'STOP':
                continue

            overlap = overlap(current_event, next_event)

            # If they don't overlap, check if it's a sequence
            if overlap <= 0.5:
                return False

            # Check if they're both stops
            if current_event['type'] == 'STOP' and next_event['type'] == 'STOP':
                return True

    return False

