    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if events[i]['type'] == 'TURN':
                continue

            # Check if current event overlaps with previous event
            overlap = max(0, min(events[j]['end'], events[i]['end']) - max(events[j]['start'], events[i]['start']))

            # If there's an overlap, check if they satisfy the conditions
            if overlap <= 0.5:
                return True

            elif overlap > 0.5 and overlap >= 0.8 * min(events[i]['duration'], events[j]['duration']):
                return True

    return False
