def matches(events):
    # Check if there are at least two events
    if len(events) < 2:
        return False

    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event to check conditions
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            # Check if the current event overlaps with the next event
            if events[i]['start'] < events[j]['start']:
                overlap = max(0, min(events[i]['end'], events[j]['end']) - max(events[i]['start'], events[j]['start']))
                if overlap <= 0.5 or -0.5 <= events[j]['start'] - events[i]['end'] <= 5.0:
                    return True
            elif events[i]['start'] == events[j]['start']:
                overlap = max(0, min(events[i]['end'], events[j]['end']) - max(events[i]['start'], events[j]['start']))
                if overlap > 0.5 and overlap >= 0.8 * min(events[i]['duration'], events[j]['duration']):
                    return True

    return False
```

