    # Check if there are at least two events
    if len(events) < 2:
        return False

    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event
    for i in range(len(events)):
        current_event = events[i]

        # If this is the first event or it doesn't overlap with previous event
        if i == 0 or overlap(events[i-1], current_event) <= 0.5:
            next_event = None

            # Find the next event that overlaps with the current event
            for j in range(i+1, len(events)):
                if overlap(current_event, events[j]) > 0.5:
                    next_event = events[j]
                    break

            # If no overlapping event found, return False
            if next_event is None:
                return False

        # Check if the current event ends after the next event starts
        elif current_event['end'] > next_event['start']:
            return False

    return True

