import math

def overlaps(a, b):
    return max(0, min(a['end'], b['end']) - max(a['start'], b['start']))

def matches(events):
    def round_corner(event1, event2):
        start_overlap = overlaps(event1, event2)
        end_overlap = overlaps(event2, event1)

        # Check if the vehicle loses speed after rounding the corner
        if start_overlap == 0:
            return False

        # Check if the vehicle stops completely or slows down significantly
        if end_overlap > 0.5 and end_overlap >= 0.8 * min(event1['duration'], event2['duration']):
            return True

    # Iterate through each pair of events to check if any satisfy the condition
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if round_corner(events[i], events[j]):
                return True

    return False

