def matches(events):
    def ahead_of_rest(event1, event2):
        start_overlap = overlaps(event1, event2)
        end_overlap = overlaps(event2, event1)

        # Check if event1 comes before event2 or vice versa
        if event1['start'] < event2['start']:
            return event1['start'] < event2['start']
        else:
            return event1['end'] < event2['end']

    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if ahead_of_rest(events[i], events[j]):
                return True
    return False

