def matches(events):
    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    prev_end = None

    for event in events:
        if 'DECELERATE' in event['type'] or 'ACCELERATE' in event['type']:
            next_event_start = events[events.index(event) + 1]['start']

            if 'TURN' in event['type']:
                if prev_end is not None and next_event_start - event['start'] <= 2.0:
                    return True

            elif 'STOP' in event['type']:
                if prev_end is not None and next_event_start - event['start'] <= 3.0:
                    return True

            prev_end = event['end']

    return False
```

