        return A['type'] == 'DECELERATE' and B['type'] == 'STOP'

    def condition3(A, B):
        return A['type'] == 'ACCELERATE' and B['type'] == 'TURN'

    def condition4(A, B):
        return A['type'] == 'STOP' and B['type'] == 'ACCELERATE'

    conditions = [condition1, condition2, condition3, condition4]

